<span class="line">  <span class="token property">left</span><span class="token punctuation">:</span>   <span class="token function">min</span><span class="token punctuation">(</span><span class="token function">anchor</span><span class="token punctuation">(</span>--c1 left<span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token function">anchor</span><span class="token punctuation">(</span>--c2 left<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
